<?php require __DIR__.'/includes/bootstrap.php';require_role('customer');if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();if(isset($_POST['cancel_booking'])){$pdo->prepare("UPDATE bookings SET status='Cancelled' WHERE id=? AND customer_id=? AND status NOT IN ('Completed','Cancelled')")->execute([intval($_POST['cancel_booking']),current_user()['id']]);flash('Booking cancelled.');redirect('my-bookings.php');}if(isset($_POST['review_booking'])){$booking=intval($_POST['review_booking']);$valid=$pdo->prepare("SELECT id,worker_id FROM bookings WHERE id=? AND customer_id=? AND status='Completed' AND worker_id IS NOT NULL");$valid->execute([$booking,current_user()['id']]);$bookingRow=$valid->fetch();$rating=intval($_POST['rating']);if($bookingRow && $rating>=1 && $rating<=5){try{$pdo->prepare("INSERT INTO reviews(booking_id,customer_id,worker_id,rating,review) VALUES(?,?,?,?,?)")->execute([$booking,current_user()['id'],$bookingRow['worker_id'],$rating,trim($_POST['review'])]);flash('Thank you for your review.');}catch(PDOException $e){flash('A review already exists for this booking.','error');}}redirect('my-bookings.php');}}$stmt=$pdo->prepare("SELECT b.*,s.name service,w.name worker_name,w.profile_photo FROM bookings b JOIN services s ON s.id=b.service_id LEFT JOIN workers w ON w.id=b.worker_id WHERE customer_id=? ORDER BY b.created_at DESC");$stmt->execute([current_user()['id']]);$rows=$stmt->fetchAll();$pageTitle='My bookings';require __DIR__.'/includes/header.php'; ?>
<section class="section"><div class="container"><div class="section-head" style="text-align:left"><div class="eyebrow">Dashboard</div><h2>My bookings</h2></div><table><thead><tr><th>Booking ID</th><th>Service</th><th>Date & time</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['booking_code'])?></td><td><?=e($r['service'])?></td><td><?=e($r['booking_date'])?> <?=substr(e($r['booking_time']),0,5)?></td><td>₹<?=number_format($r['total_amount'],0)?></td><td><span class="status"><?=e($r['status'])?></span></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5">You have no bookings yet. <a href="services.php">Book a service</a></td></tr><?php endif?></tbody></table><?php foreach($rows as $r): if($r['status']==='Completed'): $review=$pdo->prepare("SELECT id FROM reviews WHERE booking_id=?");$review->execute([$r['id']]);if(!$review->fetch()): ?><form method="post" class="card" style="margin-top:18px"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="review_booking" value="<?=e($r['id'])?>"><h3>Review <?=e($r['worker_name'] ?? 'your worker')?></h3><label class="field"><span>Rating</span><select name="rating"><option value="5">5 - Excellent</option><option value="4">4 - Good</option><option value="3">3 - Average</option><option value="2">2 - Poor</option><option value="1">1 - Very poor</option></select></label><label class="field"><span>Your review</span><textarea name="review" required></textarea></label><button class="btn btn-primary">Submit review</button></form><?php endif; elseif(!in_array($r['status'],['Completed','Cancelled'],true)): ?><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="btn btn-outline" name="cancel_booking" value="<?=e($r['id'])?>" onclick="return confirm('Cancel this booking?')">Cancel</button></form><?php endif; endforeach ?></div></section><?php require __DIR__.'/includes/footer.php'; ?>